
-- Arbeitsrecht Berufsbildung > Kündigungsschutz > Schriftform (§ 2 NachwG) > Inhalte wie Arbeitszeit
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb die Arbeitszeit eines Fachinformatikers gemäß § 2 NachwG schriftlich nachweisen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 Abs. 1 Nr. 5 NachwG verlangt die Angabe der Arbeitszeit"}, {"text": "Nein", "correct": false, "because": "Arbeitszeit ist wesentliche Vertragsbedingung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb die Arbeitszeit eines Fachinformatikers nur mündlich festlegen, ohne sie schriftlich nachzuweisen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG fordert schriftlichen Nachweis der Arbeitszeit"}, {"text": "Ja", "correct": false, "because": "Schriftform ist vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die schriftliche Angabe der Arbeitszeit eines Fachinformatikers auch Überstunden umfassen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt Angaben zu Überstundenvergütung"}, {"text": "Nein", "correct": false, "because": "Überstunden sind Teil der Arbeitszeitregelung"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb die Arbeitszeit eines Fachinformatikers per SMS schriftlich nachweisen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 2 NachwG verlangt eigenhändige Unterschrift, keine elektronische Form"}, {"text": "Ja", "correct": false, "because": "SMS genügt nicht der Schriftform"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker berechtigt, die schriftliche Festlegung seiner Arbeitszeit einzufordern?', 2, '[{"text": "Ja", "correct": true, "because": "§ 2 NachwG gibt ihm dieses Recht"}, {"text": "Nein", "correct": false, "because": "Nachweis ist Pflicht des Betriebs"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verlangt die schriftliche Angabe der Arbeitszeit eines Fachinformatikers?', 2, '[{"text": "§ 2 NachwG", "correct": true, "because": "Regelt den schriftlichen Nachweis inklusive Arbeitszeit"}, {"text": "§ 22 BBiG", "correct": false, "because": "Bezieht sich auf Kündigungen"}, {"text": "§ 3 ArbZG", "correct": false, "because": "Regelt Arbeitszeit, nicht Nachweis"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information zur Arbeitszeit muss ein Betrieb einem Fachinformatiker schriftlich nachweisen?', 3, '[{"text": "Die vereinbarte tägliche Arbeitszeit", "correct": true, "because": "§ 2 Abs. 1 Nr. 5 NachwG fordert dies"}, {"text": "Nur die Pausenzeiten", "correct": false, "because": "Zu unvollständig"}, {"text": "Die bevorzugte Arbeitszeit des Auszubildenden", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie lange hat ein Betrieb Zeit, die Arbeitszeit eines Fachinformatikers schriftlich nachzuweisen?', 2, '[{"text": "Spätestens 1 Monat nach Beginn", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}, {"text": "Innerhalb von 6 Monaten", "correct": false, "because": "Zu spät"}, {"text": "Jederzeit während der Ausbildung", "correct": false, "because": "Frist ist vorgegeben"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, die Arbeitszeit eines Fachinformatikers schriftlich nachzuweisen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 2 NachwG verpflichtet den Arbeitgeber"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine Rolle"}, {"text": "Der Auszubildende", "correct": false, "because": "Nicht seine Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb die Arbeitszeit eines Fachinformatikers nicht schriftlich nachweist?', 3, '[{"text": "Der Auszubildende kann Nachbesserung verlangen", "correct": true, "because": "§ 2 NachwG ist einklagbar"}, {"text": "Die Arbeitszeit gilt als ungültig", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Keine Konsequenzen", "correct": false, "because": "Verstoß hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitszeit-Aspekte müssen gemäß § 2 NachwG für einen Fachinformatiker schriftlich nachgewiesen werden?', 4, '[{"text": "Tägliche Arbeitszeit", "correct": true, "because": "§ 2 Abs. 1 Nr. 5 NachwG fordert dies"}, {"text": "Überstundenregelung", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt dies"}, {"text": "Pausenzeiten nach Wahl", "correct": false, "because": "Nicht relevant"}, {"text": "Vergütung für Überstunden", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG schreibt dies vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen gelten für den Nachweis der Arbeitszeit eines Fachinformatikers gemäß § 2 NachwG?', 3, '[{"text": "Schriftform mit Unterschrift", "correct": true, "because": "§ 2 NachwG verlangt dies"}, {"text": "Frist von 1 Monat nach Beginn", "correct": true, "because": "§ 2 Abs. 1 NachwG legt dies fest"}, {"text": "Elektronische Übermittlung", "correct": false, "because": "Nicht ausreichend"}, {"text": "Angabe der Arbeitszeitdauer", "correct": true, "because": "Wesentliche Bedingung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Betrieb bei der schriftlichen Angabe der Arbeitszeit eines Fachinformatikers beachten?', 4, '[{"text": "Tägliche Arbeitszeit angeben", "correct": true, "because": "§ 2 Abs. 1 Nr. 5 NachwG fordert dies"}, {"text": "Überstundenregelung dokumentieren", "correct": true, "because": "§ 2 Abs. 1 Nr. 6 NachwG verlangt dies"}, {"text": "Nur mündliche Absprache", "correct": false, "because": "Schriftform ist Pflicht"}, {"text": "Eigenhändige Unterschrift", "correct": true, "because": "§ 2 NachwG schreibt dies vor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der die Arbeitszeit eines Fachinformatikers nicht schriftlich nachweist?', 3, '[{"text": "Nachforderung durch den Auszubildenden", "correct": true, "because": "§ 2 NachwG ist einklagbar"}, {"text": "Bußgeld bei Verstößen", "correct": true, "because": "Verstoß kann sanktioniert werden"}, {"text": "Automatische Vertragsauflösung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK kann eingreifen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Betrieb bei der schriftlichen Festlegung der Arbeitszeit eines Fachinformatikers nicht tun?', 3, '[{"text": "Mündlich vereinbaren ohne Nachweis", "correct": true, "because": "§ 2 NachwG verbietet dies"}, {"text": "Per E-Mail ohne Unterschrift nachweisen", "correct": true, "because": "Schriftform erfordert Unterschrift"}, {"text": "Tägliche Arbeitszeit angeben", "correct": false, "because": "Das ist Pflicht"}, {"text": "Überstundenregelung festlegen", "correct": false, "because": "Das ist zulässig"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Arbeitszeit eines Fachinformatikers muss schriftlich nachgewiesen werden. b) Eine mündliche Vereinbarung genügt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 2 NachwG fordert die Angabe der Arbeitszeit. b) Überstunden müssen nicht erwähnt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Arbeitszeit Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Nachweis der Arbeitszeit muss innerhalb von 1 Monat erfolgen. b) Eine elektronische Form genügt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "1 Monat Frist, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Betrieb muss die Arbeitszeit eines Fachinformatikers schriftlich festlegen. b) Der Nachweis kann nach 6 Monaten erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schriftform Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die Arbeitszeit ist eine wesentliche Vertragsbedingung gemäß § 2 NachwG. b) Ein Fachinformatiker kann auf den schriftlichen Nachweis verzichten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Arbeitszeit wesentlich, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

